 1→"use client";
 2→
 3→import { useEffect, useState } from "react";
 4→import Link from "next/link";
 5→import styles from "./Footer.module.css";
 6→
 7→export function Footer() {
 8→  const [hovered, setHovered] = useState(false);
 9→  const [weather, setWeather] = useState<{ temp: number; icon: string } | null>(null);
10→
11→  useEffect(() => {
12→    fetch("https://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.006&current=temperature_2m,weather_code&temperature_unit=fahrenheit")
13→      .then((r) => r.json())
14→      .then((d) => {
15→        if (d.current) {
16→          const temp = Math.round(d.current.temperature_2m);
17→          const code = d.current.weather_code;
18→          let icon = "Clear";
19→          if (code === 0) icon = "Clear";
20→          else if (code <= 3) icon = "Partly cloudy";
21→          else if (code <= 48) icon = "Cloudy";
22→          else if (code <= 67) icon = "Rain";
23→          else if (code <= 77) icon = "Snow";
24→          else if (code <= 82) icon = "Rain";
25→          else if (code <= 86) icon = "Snow";
26→          else icon = "Storm";
27→          setWeather({ temp, icon });
28→        }
29→      })
30→      .catch(() => {});
31→  }, []);
32→
33→  return (
34→    <footer style={{ position: "relative", zIndex: 1 }}>
35→      <div
36→        className={styles.ctaBlock}
37→        onMouseEnter={() => setHovered(true)}
38→        onMouseLeave={() => setHovered(false)}
39→      >
40→        <Link href="/about" style={{ display: "block", cursor: "pointer" }}>
41→          <p className={styles.ctaText} style={{ color: hovered ? "var(--muted)" : "var(--text)" }}>
42→            Let&apos;s Work Together
43→          </p>
44→        </Link>
45→        <p className={styles.ctaEmail}>
46→          <a href="https://www.linkedin.com/in/jaimeibrahim/" target="_blank" rel="noopener noreferrer" style={{ color: "inherit" }}>
47→            Connect on LinkedIn
48→          </a>
49→        </p>
50→      </div>
51→
52→      <div className={styles.infoBar}>
53→        <span className={styles.socials}>
54→          <a href="https://www.linkedin.com/in/jaimeibrahim/" target="_blank" rel="noopener noreferrer" className={styles.socialLink} aria-label="LinkedIn">
55→            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
56→              <path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433a2.062 2.062 0 01-2.063-2.065 2.064 2.064 0 112.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z" />
57→            </svg>
58→          </a>
59→          <a href="https://www.instagram.com/jaimeibrahim/" target="_blank" rel="noopener noreferrer" className={styles.socialLink} aria-label="Instagram">
60→            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
61→              <path d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zM12 0C8.741 0 8.333.014 7.053.072 2.695.272.273 2.69.073 7.052.014 8.333 0 8.741 0 12c0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98C8.333 23.986 8.741 24 12 24c3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98C15.668.014 15.259 0 12 0zm0 5.838a6.162 6.162 0 100 12.324 6.162 6.162 0 000-12.324zM12 16a4 4 0 110-8 4 4 0 010 8zm6.406-11.845a1.44 1.44 0 100 2.881 1.44 1.44 0 000-2.881z" />
62→            </svg>
63→          </a>
64→        </span>
65→        <span className={styles.copyright}>
66→          &copy; 2026 Jaime Ibrahim &nbsp;&nbsp;|&nbsp;&nbsp; Brand Design Director &nbsp;&nbsp;|&nbsp;&nbsp; New York City
67→          {weather && (
68→            <span style={{ opacity: 0.5, fontSize: 11 }}>
69→              &nbsp;&nbsp;{weather.icon} {weather.temp}&deg;F
70→            </span>
71→          )}
72→        </span>
73→      </div>
74→    </footer>
75→  );
76→}
